/* Shared exit/focus/navigation support; no timer stop or alert acknowledgement. */
(function(root){'use strict';const allowed=new Set(['home','wardrobe','games','reminders']);const drafts=new Map(),prepared=new WeakSet(),restoredForms=new WeakSet();let applying=false,latestFocus=null,gameKey=null;
const historyOK=()=>!!root.history?.pushState;
function remember(){for(const form of document.querySelectorAll('#content form,#routine-parent form,dialog form')){const fields={};for(const el of form.querySelectorAll('input,textarea,select'))if(el.type!=='password'&&(el.id||el.name))fields[el.id||el.name]={value:el.value,checked:el.checked};if(form.id)drafts.set(form.id,fields);}}
function restoreForm(form){const fields=drafts.get(form.id);if(!fields)return;for(const el of form.querySelectorAll('input,textarea,select')){const f=fields[el.id||el.name];if(f){el.value=f.value;if(el.type==='checkbox')el.checked=f.checked;if(el.tagName==='SELECT')el.onchange?.();}}}
function restore(){for(const form of document.querySelectorAll('#content form,#routine-parent form,dialog form'))restoreForm(form);}
function entry(p,replace=false,dialog=null){if(!historyOK()||applying)return;const h=root.history;if(h.state?.diaDialog&&!dialog)replace=true;if(h.state?.diaPage===p&&h.state?.diaDialog===dialog&&(p!=='games'||JSON.stringify(h.state?.diaGame||null)===(gameKey||'null')))return;h[replace?'replaceState':'pushState']({diaPage:p,diaDialog:dialog,diaGame:p==='games'&&gameKey?JSON.parse(gameKey):null},'',root.location.pathname+root.location.search+'#'+p);}
function targetFocus(el){const replacement=el?.id?document.getElementById(el.id):el?.dataset?.reward?[...document.querySelectorAll('[data-reward]')].find(b=>b.dataset.reward===el.dataset.reward&&b.dataset.id===el.dataset.id):null;if(el?.isConnected)el.focus();else if(replacement)replacement.focus();else (document.querySelector('[data-ux-back]')||document.querySelector('#routine-help')||document.querySelector('nav [aria-current=page]'))?.focus();}
function enhance(dialog){let close=dialog.querySelector('[data-ux-close],.close,[aria-label="Close family demo"]');if(!close){close=document.createElement('button');close.type='button';close.className='secondary ux-dialog-close';close.dataset.uxClose='';close.textContent='Close';close.setAttribute('aria-label','Close '+(dialog.querySelector('h1,h2')?.textContent||'dialog'));close.onclick=()=>dialog.close();dialog.prepend(close);}}
function prepareDialog(dialog){if(prepared.has(dialog))return;if(typeof dialog.showModal!=='function'){enhance(dialog);return;}prepared.add(dialog);let opener=null;const open=dialog.showModal.bind(dialog),closeDialog=dialog.close.bind(dialog);dialog.close=function(){remember();return closeDialog();};dialog.showModal=function(){opener=document.activeElement?.isConnected?document.activeElement:latestFocus;enhance(dialog);if(!dialog.getAttribute('aria-labelledby'))dialog.setAttribute('aria-label',dialog.querySelector('h1,h2')?.textContent||'DiaBuddy dialog');entry(page,false,dialog.id);return open();};dialog.addEventListener('close',()=>{if(dialog.open)return;const restoreFocus=()=>{if(!document.querySelector('dialog[open]'))targetFocus(opener);};if(typeof queueMicrotask==='function')queueMicrotask(restoreFocus);else Promise.resolve().then(restoreFocus);if(!applying&&historyOK()&&root.history.state?.diaDialog===dialog.id)root.history.back();});enhance(dialog);}
function refresh(){for(const dialog of document.querySelectorAll('dialog')){prepareDialog(dialog);enhance(dialog);for(const form of dialog.querySelectorAll('form'))if(!restoredForms.has(form)){restoreForm(form);restoredForms.add(form);}}for(const detail of document.querySelectorAll('details')){if(detail.querySelector('[data-ux-collapse]'))continue;const b=document.createElement('button');b.type='button';b.className='text-link';b.dataset.uxCollapse='';b.textContent='Collapse section';b.onclick=()=>{detail.open=false;detail.querySelector('summary')?.focus();};detail.appendChild(b);}const host=document.querySelector('#content');if(host&&!host.querySelector('[data-ux-back]')&&page!=='home'){const b=document.createElement('button');b.className='secondary ux-page-back';b.dataset.uxBack='';b.textContent='Done · Back to my buddy';b.onclick=()=>go('home');host.prepend(b);}const parent=document.querySelector('#routine-parent');if(parent&&!parent.hidden&&!parent.querySelector('[data-ux-parent-done]')){const b=document.createElement('button');b.className='secondary ux-page-back';b.dataset.uxParentDone='';b.textContent='Done · Child view';b.onclick=()=>go('home');parent.prepend(b);}}
const baseGo=go;go=function(p){remember();if(!allowed.has(p))p='home';root.DiaGlucoseDemo?.exit(false);const selector=document.querySelector('#portal-select');if(selector?.value==='parent'){selector.value='child';selector.onchange();}baseGo(p);restore();refresh();entry(p);};
root.DiaUX={status(g){const b=document.querySelector('#ux-care-access');if(b){b.textContent=g.valid&&g.band==='low'?'Low range · Parent / help':'Parent / help';b.dataset.low=String(g.valid&&g.band==='low');}},gameOpened(game,index){gameKey=JSON.stringify({game,index});entry('games');},gameCatalog(){gameKey=null;entry('games');},prepareDialog,refresh,remember,restore,portalRendered(parent){if(parent){restore();refresh();entry('parent');}}};
document.addEventListener('focusin',e=>{latestFocus=e.target;});document.addEventListener('submit',e=>{if(e.target.id)drafts.delete(e.target.id);});document.addEventListener('keydown',e=>{if(e.key!=='Escape')return;const dialogs=[...document.querySelectorAll('dialog')].filter(d=>d.open);if(dialogs.length){e.preventDefault();e.stopImmediatePropagation();dialogs.at(-1).close();return;}if(document.querySelector('.family-tour')){root.DiaFamilyTour?.stopForCare();return;}const popup=document.querySelector('.reminder-popup');if(popup){popup.remove();return;}const expanded=document.querySelector('details[open]');if(expanded){expanded.open=false;expanded.querySelector('summary')?.focus();}},true);
if(historyOK()){const initial=root.location.hash?.slice(1);if(allowed.has(initial)&&initial!==page){applying=true;go(initial);applying=false;}entry(page,true);root.addEventListener('popstate',e=>{applying=true;try{remember();for(const d of document.querySelectorAll('dialog'))if(d.open)d.close();const p=e.state?.diaPage||'home';if(p==='parent'){const s=document.querySelector('#portal-select');s.value='parent';s.onchange();}else if(p!==page||document.querySelector('#content')?.hidden)go(p);else if(p==='games'){const key=e.state?.diaGame?JSON.stringify(e.state.diaGame):null;if(key!==gameKey){if(e.state?.diaGame)root.DiaArcade.open(e.state.diaGame.game,e.state.diaGame.index);else root.DiaArcade.show();}}restore();refresh();}finally{applying=false;}});}
const help=document.createElement('button');help.id='ux-care-access';help.className='secondary';help.textContent='Parent / help';help.onclick=()=>root.DiaMealRoutine.help();document.body.appendChild(help);
if(typeof MutationObserver==='function'){const observer=new MutationObserver(()=>refresh());observer.observe(document.body,{childList:true,subtree:true});}refresh();
})(window);
